"""Voice-stream implementation of :class:`ChannelController`.

Only references the channel types under ``TYPE_CHECKING`` so this module stays a runtime
leaf (core imports the protocol and must not pull in the channel).
"""

from __future__ import annotations

from typing import TYPE_CHECKING

import structlog

from rasa.core.channels.voice_stream.channel_controller.channel_controller import (
    ChannelCommand,
    ChannelController,
)

structlogger = structlog.get_logger()

if TYPE_CHECKING:
    from rasa.core.channels.conversation_queue.queue import ConversationQueue
    from rasa.core.channels.voice_ready.utils import CallParameters
    from rasa.core.channels.voice_stream.voice_channel import VoiceInputChannel
    from rasa.core.voice.event_composition.events.input_events import VoiceInputEvent


class VoiceChannelController(ChannelController):
    """Voice-stream :class:`ChannelController`, one per call.

    Binds the input channel plus the call-time context needed for lifecycle actions.
    """

    def __init__(
        self,
        input_channel: VoiceInputChannel,
        input_queue: ConversationQueue[VoiceInputEvent],
        call_parameters: CallParameters,
    ) -> None:
        """Create a controller for one voice call.

        Args:
            input_channel: The channel that owns the call lifecycle.
            input_queue: Raw event queue the input channel pushes into to end the call.
            call_parameters: Per-call identity/routing metadata the channel actions need
                (e.g. stream id for the client flush message).
        """
        self._input_channel = input_channel
        self._input_queue = input_queue
        self._call_parameters = call_parameters

    async def invoke(self, command: ChannelCommand) -> None:
        """Run the channel action named by ``command``."""
        if command == ChannelCommand.HANGUP:
            await self._hangup()

    async def _hangup(self) -> None:
        """End the call by enqueuing a session-ended event."""
        structlogger.debug(
            "voice_channel_controller.hangup",
            call_id=self._call_parameters.call_id,
        )
        await self._input_channel.handle_disconnect(
            self._input_queue, self._call_parameters
        )
